const equippedSkill=jobSkillById(player.job,player.equippedJobSkill)||JOB_SKILLS[player.job][0];$('attackBtn').disabled=!player.hp||!enemy.hp;$('skillBtn').disabled=mainSkillState(equippedSkill)!=='可施放';$('skillBtn').textContent=`✦ ${equippedSkill.name} (-${equippedSkill.mp} SP)`;$('skillBtn').title=jobSkillSpec(equippedSkill,player.jobSkills[equippedSkill.id],player.job,skillContext(equippedSkill)).text;if($('selectedSkillInfo'))$('selectedSkillInfo').innerHTML=`<b>目前人物技能：${equippedSkill.name} Lv.${player.jobSkills[equippedSkill.id]||0} · SP ${equippedSkill.mp}</b><span>${jobSkillSpec(equippedSkill,player.jobSkills[equippedSkill.id],player.job,skillContext(equippedSkill)).text}</span><span>${mainSkillState(equippedSkill)}</span>`;$('captureBtn').hidden=!map.capture;$('fleeBossBtn').hidden=!mapRules(player.location).bosses;$('captureBtn').disabled=!player.hp||!enemy.hp||!map.capture||enemy.boss;$('captureBtn').textContent=enemy.boss?'♛ 首領不可捕捉':map.capture?'◈ 丟球捕捉':'◈ 此地禁止捕捉';$('fleeBossBtn').disabled=!enemies.some(e=>e.boss&&e.hp>0);$('autoBtn').textContent=auto?'⏸ 暫停自動戰鬥':'▶ 開始自動戰鬥';$('autoBtn').setAttribute('aria-pressed',String(auto));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderSide();
