function reportMetrics(r){const contribution=combatContribution(r.metrics);const owner=(r.metrics.playerDamage||0)+(r.metrics.playerBuffDamage||0),pet=(r.metrics.petDamage||0)+(r.metrics.resonanceDamage||0)+(r.metrics.buffDamage||0),total=owner+pet;return `${r.scoringVersion===61?'':'<div class="report-notice">舊版戰報：採用舊版防禦或增益歸屬方式，保留原始紀錄，不納入新版總貢獻比較。</div>'}<div class="report-notice">${r.scoringVersion===61&&contribution.total?`戰鬥貢獻參考值：人物 ${(contribution.ownerShare*100).toFixed(1)}%／寵物 ${((1-contribution.ownerShare)*100).toFixed(1)}%<br>`:''}${total?`傷害來源：人物 ${(owner/total*100).toFixed(1)}%／寵物 ${(pet/total*100).toFixed(1)}%`:'尚無傷害資料'}；參考評分以傷害、有效治療、實際吸收護盾、實際承傷與防禦減傷的 HP 等值計算。重複的受傷紀錄與攔截估算不再加分，防禦減傷以受擊前HP＋護盾為有效上限，SP 及打斷次數另列；比例會隨敵人與隊伍需求變動，不代表固定戰力。</div>`+`<div class="report-grid">${FIELDS.map(key=>`<div class="report-metric"><small>${NAMES[key]}</small><strong>${Math.round(r.metrics[key]||0).toLocaleString('zh-TW')}</strong></div>`).join('')}</div>`;}
function reportName(r){return `${SPECIES[r.monster]?.name||'未知敵人'} · ${r.petName||'未出戰'}`;}
function renderReports(){const history=player.battleHistory||[];let html='<div class="item"><b>有效戰鬥貢獻</b><p>總評分包含實際傷害、未溢補治療、實際吸收護盾、實際承傷與防禦減傷。攻擊、魔法寵偏重輸出；防禦、輔助寵偏重保護與續航。每項均以 HP 等值計分並依來源歸屬；SP另列，不重複計算估算項目。</p></div>';if(report){html+=`<div class="report-card"><div class="report-title"><b>● 本場進行中</b><span class="pill">${escapeHtml(reportName(report))}</span></div>${reportMetrics(report)}</div>`;}else html+='<p class="muted">目前沒有進行中的戰鬥。</p>';html+='<div class="report-notice">BUFF 額外傷害包含寵物自主祝福與元素印記提供的實際額外傷害；控制、打斷仍待未來技能實裝。防禦寵物攔截值依敵方攻擊與玩家防禦估算，非實際承傷；護盾僅記錄已吸收部分。戰報保留最近 12 場並隨角色存檔。</div><h2 style="margin-top:16px">最近戰報</h2>';html+=history.length?`<div class="report-history">${history.slice().reverse().map(r=>`<details><summary><b>${escapeHtml(r.outcome)}</b> · ${escapeHtml(reportName(r))} · ${Math.max(0,Math.round(((r.endedAt||r.startedAt)-r.startedAt)/1000))} 秒</summary>${reportMetrics(r)}</details>`).join('')}</div>`:'<div class="empty">還沒有已結束的戰鬥。打倒一隻怪物後即可查看報告。</div>';return html;}
function renderPetSkillConfig(){const pet=activePet();if(!pet)return '<div class="item">先選擇一隻出戰寵物，再配置牠的技能與裝備。</div>';const role=companionRole(pet);return `<div class="item"><b>${escapeHtml(pet.nickname)} · 三部位裝備</b><p>寵物裝備可強化 ATK、MATK、HP、DEF、HIT、FLEE 與 ASPD，魔法型以 MATK 計算傷害。融合攻擊／魔法型會把裝備另一種攻擊能力的80%轉為主攻能力，原裝備仍可發揮作用。</p>${Object.entries(PET_SLOTS).map(([slot,name])=>{const g=pet.gear?.[slot];return `<div class="skill-option"><b>${name}：${g?escapeHtml(g.name):'未裝備'}</b>${g?`<small>${gearLabel(g)} · ${Object.entries(g.affixes||{}).map(([k,v])=>affixLabel(k,v)).join('、')}</small><button data-petoff="${slot}">卸下</button>`:''}</div>`}).join('')}</div><div class="item"><b>${escapeHtml(pet.nickname)} · 自動技能配置 · 已配置 ${(pet.equippedSkills||[]).length}／${petSkillLimit(pet)}</b>${pet.fusion&&(pet.equippedSkills||[]).length<3?'<p class="report-notice">融合寵現在可配置3招；已保留原本配置，可自行追加技能並調整順序。</p>':''}<p>${fusedPair(pet)?.name||petAbilitySetName(pet.rarity)} · ${pet.fusion?'融合專屬6招（可選3招）':'每組6招'}，隨寵物等級解鎖，可裝備${petSkillLimit(pet)}招。普通→稀有→罕見各強化6%；傳說與神話各再強化12.5%。技能獨立於普攻自動施放，不需等普攻命中或留下存活敵人；技能依裝備順序嘗試，共用0.85秒施放間隔，並消耗寵物 SP。下方預估依目前寵物能力（含裝備）計算；實際回復依缺額、主人與夥伴護盾各以自身最大HP的25%為上限，護盾優先以70%額度保護寵物、餘額給主人，各以自身最大HP25%為上限；護盾會被攻擊消耗，6.5秒後消退，並非整段冷卻都存在。增益以施放當下能力決定。</p>${(fusionSkills(pet)||petSkillsFor(role,pet.rarity)).map(s=>{const equipped=(pet.equippedSkills||[]).includes(s.id),unlocked=pet.level>=s.unlock;return `<div class="skill-option"><b>${equipped?`${pet.equippedSkills.indexOf(s.id)+1}. `:''}${s.name}</b><small>${s.description}<br>${petSkillPreview(s,petStats(pet),role)} · SP ${6+s.unlock*2} · ${Number((s.cooldown/1000).toFixed(1))}秒冷卻 · Lv.${s.unlock}${equipped?`<br>自動施放狀態：${petSkillStatus(pet,s)}${['shield','guard'].includes(s.kind)?`<br>目前寵物護盾 ${Math.max(0,petEffects.shield||0)} · 主人護盾 ${Math.max(0,player.shield||0)}（0表示已消耗或到期）`:''}`:''}</small><button data-petskill="${pet.id}:${s.id}" ${unlocked?'':'disabled'}>${equipped?'卸下':unlocked?'裝備':'未解鎖'}</button>${equipped?`<button data-petskillmove="${pet.id}:${s.id}:-1" ${pet.equippedSkills.indexOf(s.id)===0?'disabled':''}>提前</button><button data-petskillmove="${pet.id}:${s.id}:1" ${pet.equippedSkills.indexOf(s.id)===pet.equippedSkills.length-1?'disabled':''}>延後</button>`:''}</div>`}).join('')}</div>`;}
function renderTransfer(){if(player.location==='skycity')return renderThirdTransfer();if(SECOND_JOBS[player.job])return `<div class="item"><b>${CLASSES[player.job].name} · 二轉已完成</b><p>${SECOND_JOBS[player.job].style} · ${rangeLabel(playerRange(player.job))}<br>一轉Job ${player.firstJobLevel} · 一轉剩餘點數 ${player.firstJobPoints||0} · 二轉剩餘點數 ${player.jobPoints}</p></div>`;return `<div class="item"><b>城鎮二轉公會</b><p>需求 Base Lv.50、Job Lv.40。保留一轉技能，補齊一轉共50點的技能總額；二轉Job重設為1。所有裝備與部位卡片維持原樣；贈送星輝罕見職業武器至背包，可自行換裝。</p>${secondJobChoices(player.job).map(([id,meta])=>`<div class="transfer-option">${spriteHtml(id,'choice')}<b>${meta.name} · ${rangeLabel(meta.range)}</b><button data-transfer="${id}" ${transferEligibility(player,id)?'disabled':''}>${transferEligibility(player,id)||'轉職為'+meta.name}</button></div>`).join('')}</div>`;}
function transferJob(target){const error=transferEligibility(player,target);if(error)return toast(error);if(player.bag.length>=2000)return toast('請先清出1格背包空間，領取轉職武器');const meta=SECOND_JOBS[target];if(!confirm(`確定二轉為「${meta.name}」？\n保留一轉技能；Job重設為1，所有裝備及卡片維持原樣；罕見職業武器放入背包。`))return;player.firstJobLevel=player.jobLevel;player.firstJobPoints=player.jobPoints;player.job=target;player.jobLevel=1;player.jobXp=0;player.jobPoints=0;const starter=rollGear(meta.weapon,Math.min(50,player.level),'uncommon');player.bag.push(starter);const learned=activeJobSkills(target).find(s=>s.branch==='second');player.jobSkills[learned.id]=1;reconcileSkillPoints(player,JOB_SKILLS[player.job],true);player.equippedJobSkill=learned.id;player.hp=stat('hp');player.mp=stat('mp');classBuffs={};jobSkillTimers={};timers.resonance=0;dirty=true;save();message(`二轉成功！現在是【${meta.name}】。`,'rare');render();}
function readinessNote(){const r=equipmentReadiness(player,player.location,rollGear,gearStatValue,SECOND_JOBS[player.job]?.weapon||({mage:'oneStaff',acolyte:'mace',archer:'shortBow',swordsman:'blade',thief:'rifle'})[player.job]);return r?`<p class="gear-readiness">裝備準備：對照前階段Lv.${r.level}完整罕見核心約${Math.round(r.ratio*100)}%。建議累積60～70%再穩定推進；不計神話特殊詞，不限制提早挑戰。寵物、配點與操作仍會影響生存。</p>`:'';}
function renderCharacterTabs(){return `<div class="section-tabs" aria-label="角色分頁">${[['attributes','人物能力'],['gear','角色裝備'],['skills','技能配置']].map(([id,label])=>`<button data-character-section="${id}" class="${characterSection===id?'active':''}">${label}</button>`).join('')}</div>`;}
function renderCharacterAttributes(){const attrs=effectiveAttributes(),bonus=jobAttributeBonus(player,SECOND_JOBS),gear=gearAttributes(player),cards=cardAttributes(player.sockets,CARDS),values={'攻擊距離':rangeLabel(playerRange(player.job)),HP:`${player.hp} / ${stat('hp')}`,SP:`${player.mp} / ${stat('mp')}`,'護盾':player.shield||0,ATK:stat('atk'),MATK:stat('matk'),DEF:stat('def'),MDEF:stat('mdef'),ASPD:stat('aspd').toFixed(1),'攻擊間隔':`${(stat('speed')/1000).toFixed(3)}秒`,'攻速加成':`${stat('aspdPct')}%`,HIT:stat('hit'),FLEE:stat('flee'),'暴擊率':`${stat('crit')}%`,'暴擊傷害':`${stat('critDmg')}%`,'無視防禦':`${stat('ignoreDef')}%`,'魔法傷害加成':`${stat('magicDamage')}%`,'最終減傷':`${stat('damageReduction')}%`,'近距離物理傷害':`×${(1+attrs.STR*.008).toFixed(3)}`,'遠距離物理傷害':`×${(1+attrs.DEX*.008).toFixed(3)}`,'魔法傷害':`×${(1+attrs.INT*.008).toFixed(3)}`,'無詠唱進度':`${attrs.INT+2*attrs.DEX} / ${freecastThreshold(player)}`};return `<div class="item"><h3>${escapeHtml(player.name)} · ${CLASSES[player.job].name}${player.reborn?' · 轉生':''}</h3><p>Base ${player.level}／${characterLevelCap(player)} · Job ${player.jobLevel}／${jobLevelCap(player)}</p><div class="allocation-summary"><b>可配置點數 <strong>${player.statPoints}</strong></b><span>單項上限 ${attributeCap(player)}</span></div><p>輸入數量後按配置；+值為Job、裝備與卡片的實際加成。</p>${Object.entries(ATTRS).map(([id,label])=>`<div class="allocation-row"><div><b>${id} ${label}</b><small>${attributeDescriptions[id]}</small></div><span title="Job +${bonus[id]}／裝備 +${gear[id]}／卡片 +${cards[id]}">${player.attributes[id]}<b class="attribute-bonus">+${attrs[id]-player.attributes[id]}</b></span><input type="number" min="1" max="${Math.max(1,Math.min(player.statPoints,attributeCap(player)-player.attributes[id]))}" value="${allocationAmounts[id]||1}" data-allocation-amount="${id}" aria-label="${label}配置數量"><button data-add="${id}" ${player.statPoints&&player.attributes[id]<attributeCap(player)?'':'disabled'}>配置</button></div>`).join('')}<p>裝備能力值合計 ${Object.values(gear).reduce((a,b)=>a+b,0)}／${gearAttributeLimit(player)}（本階可配置點數30%，單項另限29／36）；卡片六項能力值合計 ${Object.values(cards).reduce((a,b)=>a+b,0)}／24。</p></div><div class="item"><h3>人物完整能力</h3><div class="numbers combat-numbers">${Object.entries(values).map(([label,value])=>`<div><span class="tiny">${label}</span><b>${value}</b></div>`).join('')}</div></div>`;}


function renderPetTabs(){return `<div class="section-tabs" aria-label="寵物分頁"><button data-pet-section="manage" class="${petSection==='manage'?'active':''}">寵物管理</button><button data-pet-section="active" class="${petSection==='active'?'active':''}">當前出戰寵物</button></div>`;}
function renderPetManagement(){return `<div class="item"><h3>寵物管理 ${player.pets.length}／30</h3><p>管理捕捉、鎖定、出戰與放生。鎖定及出戰中的寵物不會被批次放生。能力與技能請到「當前出戰寵物」。</p><div class="panel-shortcuts"><button data-release-select="all">全選可放生</button><button data-release-select="none">取消全選</button><button data-release-batch>放生已選（${selectedReleasePets.size}）</button></div><label>依品質放生<select data-release-rarity>${PET_RARITIES.map(r=>`<option value="${r.id}" ${releaseRarity===r.id?'selected':''}>${r.name}及以下</option>`).join('')}</select></label><button data-release-below class="danger">確認放生所選品質及以下</button><p>捕捉品質：普通70%／稀有25%／罕見4%／傳說1%，不直接捕捉神話。</p></div>${player.pets.map(p=>{const active=p.id===player.activePetId,step=nextPetEvolution(p),ready=step&&p.level>=step.level;return `<div class="item" data-ui-key="pet-${p.id}"><label><input type="checkbox" data-release-check="${p.id}" ${selectedReleasePets.has(p.id)?'checked':''} ${active||p.locked?'disabled':''}>選擇放生</label><div class="itemhead"><b>${petIcon(p)} ${escapeHtml(petForm(p)||p.nickname)}</b><span class="grade-${p.rarity}">${petRarity(p).name}</span></div><p>Lv.${p.level} · ${fusedPair(p)?.name||SPECIES[p.species].roleName} · ${active?'出戰中':p.locked?'已鎖定':'未出戰'}${ready?' · 可回村莊進化':''}</p><button data-pet="${p.id}">${active?'收回':'出戰並配置'}</button><button data-pet-lock="${p.id}">${p.locked?'解除鎖定':'鎖定'}</button><button data-release="${p.id}" ${p.locked?'disabled':''}>放生</button>${ready?`<button ${isTown(player.location)?`data-evolve="${p.id}"`:'data-town'}>${isTown(player.location)?'村莊進化':'回村莊進化'}</button>`:''}</div>`;}).join('')||'<div class="item">尚無寵物。</div>'}${isTown(player.location)?'<details class="item"><summary>村莊進化規則與靈核合成</summary>'+renderEvolution(false)+'</details>':'<p>進化只能回村莊進行。</p>'}`;}
function renderActiveCompanion(){const p=activePet();if(!p)return '<div class="item">尚無出戰寵物，請先到寵物管理選擇夥伴。</div>';const stats=petStats(p);return `<div class="item loyalty-panel"><b>忠誠度 ${p.loyalty||0}／${LOYALTY_MAX}</b><p>出戰且存活、怪物與寵物等差±40以內，每累積${LOYALTY_PER_POINT}隻+1；目前進度 ${p.loyaltyKills||0}／${LOYALTY_PER_POINT}。界限進化消耗${ASCENSION_LOYALTY}忠誠度。${p.fusion?'已完成融合進化 · 上限200':p.ascended?'已完成界限進化／異化 · 上限150 · 額外核心能力+15%':'上限99；需完成99級界限進化／異化後才開放150'}</p></div><div class="item"><h3>${escapeHtml(petForm(p)||p.nickname)}</h3>${p.sealedProgress?`<p>已封存Lv.${p.sealedProgress.level}的舊進度，完成界限進化／異化後恢復；超過目前等級的寵物裝備暫不生效。</p>`:''}${petSprite(p,'pet')}<p>${petRarity(p).name} · ${fusedPair(p)?.name||SPECIES[p.species].roleName} · Lv.${p.level}</p><div class="pet-live-shield"><b>◇ 寵物目前護盾 ${Math.max(0,petEffects.shield||0)}</b>${meter(petEffects.shield||0,Math.round(stats.hp*.25),'shield')}</div><div class="numbers">${['hp','sp','atk','matk','def','mdef','aspd','hit','flee','crit'].map(key=>`<div><small>${key.toUpperCase()}</small><b>${stats[key]}</b></div>`).join('')}</div>${nextPetEvolution(p)&&p.level>=nextPetEvolution(p).level?'<p class="evolution-ready">已達進化等級，請回村莊進化。</p>':''}</div>`+renderPetSkillConfig();}
function setJunkSelection(enabled,map=null){const ids=Object.entries(ITEMS).filter(([,it])=>it.junk&&(map===null||(map==='legacy'?!it.map:it.map===map))).map(([id])=>id),selected=new Set(map===null?[]:player.autoSellJunk);for(const id of ids){if(enabled)selected.add(id);else selected.delete(id);}player.autoSellJunk=[...selected];if(enabled)autoSellSelected();dirty=true;save();renderSide(true);}
function renderJunkSettings(){return `<div class="item"><h3>自動出售雜物</h3><p>只出售勾選的雜物。已接取任務所需的指定雜物會保留${QUEST_REQUIREMENTS.junk}個；征途誓印不會出售。線上與離線皆適用。</p><div class="panel-shortcuts"><button data-junk-bulk="all:on">全部勾選</button><button data-junk-bulk="all:off">全部取消</button></div>${[{id:'petland',name:'寵物之地'},...ZONES].map(z=>`<details><summary>${z.name}</summary><button data-junk-bulk="${z.id}:on">本區全選</button><button data-junk-bulk="${z.id}:off">本區取消</button>${Object.entries(ITEMS).filter(([,it])=>it.junk&&it.map===z.id).map(([id,it])=>`<label class="setting-toggle"><input type="checkbox" data-junk-sell="${id}" ${player.autoSellJunk.includes(id)?'checked':''}>${it.name} · ${it.cost}金</label>`).join('')}</details>`).join('')}<details><summary>舊版雜物</summary><button data-junk-bulk="legacy:on">本區全選</button><button data-junk-bulk="legacy:off">本區取消</button>${Object.entries(ITEMS).filter(([,it])=>it.junk&&!it.map).map(([id,it])=>`<label><input type="checkbox" data-junk-sell="${id}" ${player.autoSellJunk.includes(id)?'checked':''}>${it.name}</label>`).join('')}</details></div>`;}
function renderVillageQuests(){if(player.location!=='town')return '<div class="item">請回靈契主城找征途引導官・艾琳接取或回報任務。</div>';return `<div class="item npc-dialog"><h3>🧭 征途引導官・艾琳</h3><p>「旅人，請先從燼火熔獄的Lv.51–60征途開始，完成後再挑戰下一區域。」</p><p>任務依51–60 → 61–70 → 71–80 → 81–90 → 91–99順序接取。接取與回報都必須回村莊找我；各區全部小怪均可遭遇，指定小怪每隻必掉1個專屬雜物，任務材料保留${QUEST_REQUIREMENTS.junk}個不自售。另需當區首領征途誓印${QUEST_REQUIREMENTS.proof}枚；避開首領不會取得。</p>${ZONES.filter(z=>z.min>=51&&z.max<=99).map(z=>{const q=player.quests[z.id],reason=q?null:questAcceptError(player,z.id),junk=q?(player.bag.find(e=>e.id===q.junk)?.qty||0):0,proof=q?(player.bag.find(e=>e.id===q.proof)?.qty||0):0;return `<div class="quest-row"><b>${z.name} Lv.${z.min}–${z.max}</b>${q?`<p>${q.done?'✓ 已完成':`${ITEMS[q.junk]?.name} ${junk}/${QUEST_REQUIREMENTS.junk}<br>${ITEMS[q.proof]?.name} ${proof}/${QUEST_REQUIREMENTS.proof}`}</p>${q.done?'':`<button data-quest-turnin="${z.id}" ${junk>=QUEST_REQUIREMENTS.junk&&proof>=QUEST_REQUIREMENTS.proof?'':'disabled'}>向艾琳回報任務</button>`}`:`<p>${reason||'可以接取此階段征途'}</p><button data-quest-accept="${z.id}" ${reason?'disabled':''}>向艾琳接取任務</button>`}</div>`;}).join('')}<h3>靈契轉生</h3><p>二轉Base99／Job50並完成五區任務。轉生回到一轉Base1／Job1，基本能力重置並獲得20點自由能力。裝備、卡片、寵物、金幣保留；忽略1–99裝備等級需求，職業限制仍有效。角色上限150，Base100起基本能力上限120；101級起可前往蒼穹機界新大陸。</p><button data-rebirth ${rebirthEligibility(player,SECOND_JOBS)?'disabled':''}>${rebirthEligibility(player,SECOND_JOBS)||'進行靈契轉生'}</button></div>`;}
function renderJobCodex(){return Object.entries(SECOND_JOBS).map(([id,job])=>`<details class="item" ${id===player.job?'open':''}><summary>${job.name} · ${rangeLabel(job.range)}</summary><div class="job-art-pair">${spriteHtml(id,'choice',false)}${spriteHtml(id,'choice',true)}</div><p>二轉外觀／轉生二轉外觀</p><p>${job.style}</p><p>一轉 ${CLASSES[job.parent].name} → ${job.name}；Base50／Job40可回村莊辦理。主要能力：${job.attribute}。</p>${JOB_SKILLS[id].filter(s=>s.branch==='second').map(skill=>`<p><b>${skill.name}</b>${skill.rebornOnly?' · 轉生二轉限定':''}<br>${skill.desc} · ${jobSkillSpec(skill,1,id).text}</p>`).join('')}<h3>三轉：${THIRD_JOBS[id].name}</h3>${spriteHtml(id,'choice',true,true)}<p>${THIRD_JOBS[id].style}</p>${JOB_SKILLS[id].filter(s=>s.thirdOnly).map(skill=>`<p><b>${skill.name}</b> · Lv.${skill.maxRank}<br>${skill.desc} · ${jobSkillSpec(skill,1,id).text}</p>`).join('')}<p>四種配寵的具體觸發、技能名稱及作用請見「共鳴玩法」。</p></details>`).join('');}
function autoQueueSkills(){return JOB_SKILLS[player.job].map(s=>({...s,learned:!!player.jobSkills[s.id]&&!supersededSkill(player,s)}));}
function renderAutoSkillSettings(){const settings=normalizeAutoSkills(player.autoSkills,autoQueueSkills()),skills=settings.order.map(id=>jobSkillById(player.job,id)),groups=new Set(skills.map(autoSkillGroup).filter(Boolean)),available=autoQueueSkills().filter(s=>s.learned&&s.kind!=='passive'&&!settings.order.includes(s.id)),defaultAdd=available.find(s=>!autoSkillGroup(s)||!groups.has(autoSkillGroup(s))),canAdd=!!defaultAdd;return `<div class="item auto-skill-settings"><h3>自動技能優先順序</h3><p>由上往下嘗試。只施放清單內的技能；學習新技能不會自動加入。移除只取消自動施放，不會遺忘技能。</p><div class="auto-skill-add"><label for="autoSkillAddSelect">選擇技能</label><select id="autoSkillAddSelect" aria-label="選擇要新增的自動技能" ${canAdd?'':'disabled'}>${available.length?available.map(skill=>{const conflict=autoSkillGroup(skill)&&groups.has(autoSkillGroup(skill));return `<option value="${skill.id}" ${defaultAdd?.id===skill.id?'selected':''} ${conflict?'disabled':''}>${skill.name} · ${skill.rebornOnly?'轉生二轉':skill.branch==='second'?'二轉':'一轉'}${conflict?'（同類護盾已配置）':''}</option>`;}).join(''):'<option value="">沒有可新增的已學技能</option>'}</select><button data-auto-skill-add ${canAdd?'':'disabled'}>新增技能</button></div><p class="tiny">同類護盾限配置一個；若要更換，先移除目前的護盾。二轉護盾CD3.6秒，一轉4.8秒，共用冷卻，無法交替連放。</p>${skills.length?skills.map((skill,index)=>`<div class="auto-skill-row"><div class="auto-skill-name"><b>${index+1}. ${skill.name}</b><small>${skill.rebornOnly?'轉生二轉':skill.branch==='second'?'二轉':'一轉'} · Lv.${player.jobSkills[skill.id]} · CD ${(skillCooldown(skill)/1000).toFixed(2)}秒</small></div><div class="auto-skill-actions"><button data-skill-move="${skill.id}" data-direction="-1" aria-label="將${skill.name}上移" ${index===0?'disabled':''}>↑</button><button data-skill-move="${skill.id}" data-direction="1" aria-label="將${skill.name}下移" ${index===skills.length-1?'disabled':''}>↓</button><button data-auto-skill-remove="${skill.id}" aria-label="移除${skill.name}" class="danger">移除</button></div></div>`).join(''):'<p class="empty">尚未配置自動技能；可從上方選擇並新增。普通攻擊仍會正常進行。</p>'}<p class="tiny">護盾低於HP15%才補盾；治療低於65%、回魔低於55%才施放。零CD攻擊排在最前可能占用其他招式的施放機會。</p></div>`;}
function changeAutoSkill(id,enabled){const previous=structuredClone(player.autoSkills),skills=autoQueueSkills(),skill=skills.find(s=>s.id===id),settings=normalizeAutoSkills(player.autoSkills,skills);if(enabled){if(!skill?.learned||skill.kind==='passive')return;const group=autoSkillGroup(skill);if(group&&settings.order.some(other=>other!==id&&autoSkillGroup(skills.find(s=>s.id===other))===group))return toast('同類護盾只能配置一個，請先移除目前的護盾');if(!settings.order.includes(id))settings.order.push(id);}else settings.order=settings.order.filter(other=>other!==id);player.autoSkills=settings;dirty=true;if(save()===false)player.autoSkills=previous;renderSide(true);}
function reorderAutoSkill(id,direction){const previous=structuredClone(player.autoSkills);player.autoSkills=moveAutoSkill(player.autoSkills,JOB_SKILLS[player.job].map(s=>({...s,learned:player.jobSkills[s.id]>0})),id,direction);dirty=true;if(save()===false)player.autoSkills=previous;renderSide(true);}
function renderCaptureSettings(){const selected=normalizeCaptureRoles(player.autoCaptureRoles);return `<div class="item"><h3>寵物之地自動捕捉</h3><p>勾選要捕捉的類型；全部關閉即停用。僅寵物之地線上自動戰鬥時丟球，不需壓低血量，其餘類型照常戰鬥。離線不捕捉。</p>${[['attack','攻擊型'],['magic','魔法型'],['defense','防禦型'],['support','輔助型']].map(([role,label])=>`<label class="setting-toggle"><input type="checkbox" data-capture-role="${role}" ${selected.includes(role)?'checked':''}> 自動捕捉${label}</label>`).join('')}<p>缺球時逐顆以金幣補球；金幣不足或寵物滿30隻時停止丟球，不會自動放生。</p></div>`;}
function autoCapturePet(now){if(offlineSimulation||!auto||!player.hp||player.location!=='petland'||!enemy?.hp||enemy.boss||now-(timers.capture||0)<1000)return;const role=SPECIES[enemy.id]?.role;if(!normalizeCaptureRoles(player.autoCaptureRoles).includes(role)||player.pets.length>=30)return;timers.capture=now;const balls=player.bag.some(e=>e.id==='orb'&&e.qty>0);if(!balls&&player.gold<ITEMS.orb.cost)return;capture();}
function renderPactStatus(){const pet=activePet(),rule=pet&&companionResonance(player,pet),a=effectiveAttributes();return `<div class="pact-status"><b>目前共鳴：${rule?.name||'未攜帶寵物'}</b><p>${rule?.description||'選擇夥伴後可查看專屬玩法。'}${player.thirdJob?`<br>目前由三轉主攻【${jobSkillById(player.job,'thirdMain_'+player.job).name}】觸發三轉專屬共鳴；範圍與終結技亦有獨立變化。`:player.reborn&&player.jobSkills['rebirthMain_'+player.job]?`<br>目前由轉生主攻【${jobSkillById(player.job,'rebirthMain_'+player.job).name}】承接此共鳴；標示「轉生主攻」的數值優先適用。`:''}${!player.thirdJob&&pet&&!fusedPair(pet)&&resonanceOpener(player.job,companionRole(pet))?`<br>建議將【${jobSkillById(player.job,resonanceOpener(player.job,companionRole(pet))).name}】排在主攻之前，滿足共鳴觸發條件；仍由你自行設定順序。`:''}${rule?.mode==='pact'?`<br>觸發：${rule.events.map(e=>RESONANCE_EVENTS[e]||jobSkillById(player.job,e)?.name||e).join('／')} · 持續${(rule.duration||6000)/1000}秒 · 冷卻${rule.cooldown/1000}秒<br>${classBuffs.pact?.until>gameNow()?'● 共鳴效果生效中':'等待職業動作觸發'}`:''}${player.job==='wizard'?`<br>無詠唱進度 INT＋2DEX：${a.INT+2*a.DEX}／${freecastThreshold(player)}（含Job、裝備與卡片）`:''}</p></div>`;}
function renderJobTree(){const branches=[...(player.thirdJob?['third']:[]),...(player.reborn&&SECOND_JOBS[player.job]?['rebirth']:[]),...(SECOND_JOBS[player.job]?['second']:[]),'first'];return renderAutoSkillSettings()+`<div class="item"><b>金幣重新訓練</b><p>每次 ${retrainCost(player.level)} 金，能力與全部職階技能點退回各自點數池。</p><button data-retrain="attributes">重置屬性</button> <button data-retrain="skills">重置技能</button></div><div class="item"><h3>${player.thirdJob?THIRD_JOBS[player.job].name:CLASSES[player.job].name} · 主動與被動技能</h3>${renderPactStatus()}<p>每提升1級Job立即給1點。轉生二轉Job51–70給轉生技能點；三轉另開獨立Job1–70與70點技能總額（初始主攻1級）。舊技能及點數保留。</p><p>三轉包含五主動×10級、四被動×5級。主攻零CD、由ASPD限制每次動作；範圍技能每體獨立計傷。巫師INT＋2DEX達${freecastThreshold(player)}可無詠唱，大型主攻仍保留0.9秒最低動作後延遲。同類護盾共用冷卻，不能同時配置。</p>${branches.map(branch=>{const pool=branch==='third'?'thirdJobPoints':branch==='rebirth'?'rebornJobPoints':branch==='first'&&SECOND_JOBS[player.job]?'firstJobPoints':'jobPoints',skills=JOB_SKILLS[player.job].filter(s=>branch==='third'?s.thirdOnly:branch==='rebirth'?s.rebornOnly:!s.rebornOnly&&!s.thirdOnly&&s.branch===branch);return `<section class="job-skill-section ${branch}"><h3>${({third:'三轉專屬',rebirth:'轉生二轉 · 主攻與常駐強化',second:'二轉專屬技能',first:'一轉基礎技能'})[branch]} · 可用 <span data-skill-points="${pool}">${player[pool]||0}</span> 點</h3>${skills.map(s=>{const rank=player.jobSkills[s.id]||0,passive=s.kind==='passive';return `<div class="skill-option"><b>${passive?'◆ 被動':'✦ 主動'} ${s.name} <span class="pill">Lv.${rank}/${s.maxRank}</span></b><small>${supersededSkill(player,s)?'已由高階主攻取代 · ':''}${s.desc}<br>${jobSkillSpec(s,Math.max(1,rank),player.job,skillContext(s)).text}${s.aoe?` · 同時攻擊最多${s.targets||3}個目標，每個目標獨立承受上述倍率`:''} · Job ${s.unlock}${passive?'':` · SP ${s.mp}`}<br>${!passive&&!canCastJobSkill(s)?'目前武器不符':'依職業裝備配置'}</small><div class="skill-actions"><button data-jobup="${s.id}" ${skillUnlocked(player,s)&&(player[pool]||0)>0&&rank<s.maxRank?'':'disabled'}>升級技能</button>${passive?'':`<button data-jobequip="${s.id}" ${rank&&!supersededSkill(player,s)&&player.equippedJobSkill!==s.id?'':'disabled'}>${player.equippedJobSkill===s.id?'預設技能':'設為預設'}</button>`}</div></div>`;}).join('')}</section>`;}).join('')}</div>`;}
function evolvePet(id){const pet=player.pets.find(p=>p.id===id),step=pet&&nextPetEvolution(pet);if(!pet||!step)return toast('寵物已達進化上限');if(!isTown(player.location))return toast('只能在城鎮進化');if(pet.level<step.level)return toast(`需寵物 Lv.${step.level}`);if((player.bag.find(e=>e.id===step.id)?.qty||0)<step.count)return toast('進化素材不足');evolutionPreview={id,before:JSON.parse(JSON.stringify(pet))};$('evolutionModal').style.display='grid';$('gameShell').inert=true;$('evolutionScene').className='evolution-scene preview';$('evolutionBefore').src=petArt(pet);$('evolutionAfter').src=petArt(pet,evolutionStage(pet)+1);$('evolutionTitle').textContent='夥伴即將迎來新的形態';$('evolutionStatus').textContent=`${petForm(pet)} → 下一階形態 · 消耗 ${ITEMS[step.id].name} ×${step.count}`;$('evolutionStart').hidden=false;$('evolutionStart').disabled=false;$('evolutionClose').disabled=false;$('evolutionClose').textContent='取消';$('evolutionStart').focus();}
function beginEvolution(){if(evolutionRunning||!evolutionPreview)return;const pet=player.pets.find(p=>p.id===evolutionPreview.id);if(!pet)return closeEvolution();const before=JSON.parse(JSON.stringify(pet)),bagBefore=JSON.parse(JSON.stringify(player.bag)),playerBefore=structuredClone(player),result=evolutionPreview.fusion?fusePets(player,pet.id,evolutionPreview.donorId):evolutionPreview.ascension?ascendPet(pet,player.bag,player.location,evolutionPreview.mode):evolveCompanion(pet,player.bag,player.location,PET_EVOLUTIONS,PET_RARITIES);if(result.error)return toast(result.error);result.form=petForm(pet);if(evolutionPreview.ascension)pet.nickname=petForm(pet);migratePetSkills(pet,companionRole(pet));pet.hp=petStats(pet).hp;pet.sp=petStats(pet).sp;if(activePet()?.id===pet.id)clearPetEffects();dirty=true;if(save()===false){player=playerBefore;return toast('存檔失敗，本次進化未扣除素材');}stopAutoFusion('寵物進化中');evolutionRunning=true;$('evolutionAfter').src=petArt(pet);$('evolutionScene').className='evolution-scene evolving';$('evolutionTitle').textContent='進化之光正在凝聚…';$('evolutionStatus').textContent='夥伴的輪廓正在變化，請稍候…';$('evolutionStart').hidden=true;$('evolutionClose').disabled=true;evolutionTimer=setTimeout(()=>{evolutionRunning=false;const mutation=!result.guaranteedLegend&&result.before!==result.after&&['legendary','mythic'].includes(result.after),failedMutation=evolutionPreview?.ascension&&evolutionPreview.mode==='mutate'&&!result.mutation;$('evolutionScene').className='evolution-scene complete';$('evolutionTitle').textContent=failedMutation?`異化未成功，夥伴維持【${result.form}】。`:result.fusion?`融合成功，誕生【${result.form}】！`:mutation?`太驚人了，居然是【${result.form}】！`:`恭喜您，進化為【${result.form}】！`;$('evolutionStatus').textContent=`${petRarity(pet).name} · ${petAbilitySetName(pet.rarity)}${result.before!==result.after?' · 品質提升成功':''}`;$('evolutionClose').disabled=false;$('evolutionClose').textContent='繼續冒險';$('evolutionClose').focus();message($('evolutionTitle').textContent,'rare');render();},4000);}
function closeEvolution(){if(evolutionRunning)return;$('evolutionModal').style.display='none';$('gameShell').inert=false;evolutionPreview=null;render();}
function renderResonanceGuide(){return renderThirdResonanceGuide()+`<div class="item"><b>一轉／二轉 × 四種寵物 · 60組核心共鳴</b><p>攻擊事件需命中，治療／回魔需實際回復；坦寵攔截需實際受擊。每個配對有一組共用冷卻，寵物共鳴不會再觸發共鳴。一轉效果依寵物裝備能力計算；二轉共鳴命中觸發時即可改造當次及後續6秒的指定技能，寵物本身攻擊／坦傷／治療仍依能力成長。</p>${Object.entries(RESONANCE_RULES).map(([job,roles])=>`<details ${job===player.job?'open':''}><summary>${CLASSES[job].name}${job===player.job?' · 目前職業':''}</summary>${Object.entries(roles).map(([role,rule])=>`<div class="skill-option"><b>${({attack:'攻擊',magic:'魔法',defense:'防禦',support:'輔助'})[role]}寵 · ${rule.name}</b><small>${rule.description}${JOB_SKILLS[job]?.some(s=>s.rebornOnly)?`<br>轉生主攻「${JOB_SKILLS[job].find(s=>s.id==='rebirthMain_'+job)?.name}」完整承接此效果並取代原主攻；常駐BUFF下，獵鷹／聖盾命中可維持原BUFF觸發的共鳴；觸發仍須滿足下方條件。`:''}<br>觸發：${rule.events.map(e=>RESONANCE_EVENTS[e]).join('／')} · CD ${(rule.cooldown/1000).toFixed(1)}秒</small></div>`).join('')}</details>`).join('')}</div>`;}

function renderCombatPanel(){
 const pet=activePet(),s=pet?petStats(pet):null;
 const values=combatView==='player'?{'職業':CLASSES[player.job].name,'攻擊距離':rangeLabel(playerRange(player.job)),'HP':`${player.hp}/${stat('hp')}`,'SP':`${player.mp}/${stat('mp')}`,ATK:stat('atk'),MATK:stat('matk'),DEF:stat('def'),MDEF:stat('mdef'),ASPD:stat('aspd').toFixed(1),HIT:Math.round(stat('hit')),FLEE:stat('flee'),CRIT:`${stat('crit').toFixed(1)}%`,'暴擊傷害':`${stat('critDmg')}%`,'無視防禦':`${stat('ignoreDef')}%`,'魔法傷害加成':`${stat('magicDamage')}%`}
 :s?{'目前形態':petForm(pet)||SPECIES[pet.species].name,'類型':(fusedPair(pet)?.name||SPECIES[pet.species].roleName),'攻擊距離':rangeLabel(companionRange(companionRole(pet))),'稀有度':petRarity(pet).name,'進化階段':`${pet.evolution||0}/4`,'等級':pet.level,'HP':`${pet.hp}/${s.hp}`,'SP':`${pet.sp}/${s.sp}`,ATK:s.atk,MATK:s.matk,DEF:s.def,MDEF:s.mdef,ASPD:s.aspd.toFixed(1),HIT:Math.round(s.hit),FLEE:Math.round(s.flee),CRIT:`${s.crit.toFixed(1)}%`}:{};
 return `<div class="item"><b>角色／寵物完整狀態面板</b><p>這裡只顯示當前實際屬性；攻擊與受傷事件請至作戰紀錄切換。</p><div class="bag-filters"><button data-combatview="player" class="${combatView==='player'?'active':''}">人物狀態</button><button data-combatview="pet" class="${combatView==='pet'?'active':''}">寵物狀態</button></div>${Object.keys(values).length?`<div class="numbers combat-numbers">${Object.entries(values).map(([k,v])=>`<div><span class="tiny">${k}</span><b>${v}</b></div>`).join('')}</div>`:'<div class="empty">尚未有出戰寵物。</div>'}</div>`;}
function renderPotionSettings(){const thresholds=normalizePotionThresholds(player.potionThresholds);return `<div class="item"><b>自動補給門檻</b><p>HP／SP 低於設定百分比時使用背包現有藥水，四項可獨立設定 1～100%。離線掛機沿用相同設定。藥水恢復量仍依藥水種類與角色／寵物能力計算。</p><div class="auto-options">${[['playerHp','玩家補血 HP'],['playerSp','玩家補魔 SP'],['petHp','寵物補血 HP'],['petSp','寵物補魔 SP']].map(([key,label])=>`<div class="potion-setting"><label><input type="checkbox" data-autopotion="${key}" ${player.autoPotions[key]?'checked':''}> ${label}</label><label>低於 <input type="number" min="1" max="100" step="1" data-potion-threshold="${key}" aria-label="${label}門檻百分比" value="${thresholds[key]}"> % 自動使用</label><label>藥水優先順序<select data-potion-priority="${key}">${[['high','由高效到低效'],['low','由低效到高效'],...(key.endsWith('Hp')?['red_small','red_mid','red_large']:['blue_small','blue_mid','blue_large']).map(id=>[id,ITEMS[id].name+'優先'])].map(([id,name])=>`<option value="${id}" ${(player.potionPriority?.[key]||'high')===id?'selected':''}>${name}</option>`).join('')}</select></label></div>`).join('')}</div></div>`;}

function equipmentLine(g){return `${g.swapProtected?`<span class="fusion-protected">換裝保留 · 自動分解保護</span><button data-swap-unprotect="${g.uid}">解除換裝保護</button>`:''}${g.fusionMatch?'<span class="fusion-protected">✦ 融合目標 · 自動分解保護</span>':''}<span class="gear-title grade-${g.rarity||'common'}">${escapeHtml(g.name)}</span> <span class="gear-grade grade-${g.rarity||'common'}">${gearLabel(g)}</span><div class="gear-affixes">${Object.entries(g.affixes||{}).map(([k,v])=>`<span>${affixLabel(k,v)}</span>`).join('')||'無額外屬性'}</div>`;}
function gearComparison(g){const base=ITEMS[g.id],pet=activePet(),isPet=!!base.petSlot;
 if(isPet&&!pet)return '<div class="gear-compare">出戰寵物後可比較數值。</div>';
 if(!isPet&&base.jobs&&!base.jobs.includes(player.job))return '<div class="gear-compare">此武器不適用目前職業。</div>';
 if(!isPet&&base.slot==='leftHand'&&GEAR_BASE[player.gear.rightHand?.id]?.hands===2)return '<div class="gear-compare">需先卸下雙手武器。</div>';
 if(!isPet&&g.id==='offDagger'&&GEAR_BASE[player.gear.rightHand?.id]?.weaponType!=='dagger')return '<div class="gear-compare">需先裝備主手匕首。</div>';
 const keys=isPet?['hp','sp','atk','matk','def','mdef','hit','flee','aspd','crit']:['hp','mp','atk','matk','def','mdef','hit','flee','aspd','crit','critDmg','ignoreDef','magicDamage'];
 const snapshot=()=>{clearStatSnapshots();return Object.fromEntries(keys.map(k=>[k,isPet?petStats(pet)[k]||0:stat(k)]));};
 const before=snapshot(),slot=base.petSlot||base.slot,gears=isPet?pet.gear:player.gear,previous=gears[slot],left=isPet?null:player.gear.leftHand,socket=isPet?null:player.sockets[slot],leftSocket=isPet?null:player.sockets.leftHand;
 try{gears[slot]=g;if(!isPet){if(slot==='rightHand'&&(base.hands===2||base.weaponType!=='dagger'&&left?.id==='offDagger')){player.gear.leftHand=null;}}const after=snapshot(),rows=keys.filter(k=>k==='atk'||k==='matk'||Math.abs(after[k]-before[k])>.001).map(k=>{const d=after[k]-before[k],positive=d>0,zero=Math.abs(d)<.001;return `<div class="compare-stat"><span>${k.toUpperCase()}</span><span>${Number(before[k].toFixed(1))} → ${Number(after[k].toFixed(1))} <b class="${zero?'delta-zero':positive?'delta-up':'delta-down'}">${zero?'±':positive?'+':''}${Number(d.toFixed(1))}</b></span></div>`});return `<div class="gear-compare"><b>與目前穿戴比較（裝備後總屬性）</b><div class="compare-stats">${rows.join('')||'<span>總屬性無變化</span>'}</div>${!isPet&&base.hands===2&&left?'<small>已包含取代左手裝備的損失</small>':''}</div>`;}finally{gears[slot]=previous;if(!isPet){player.gear.leftHand=left;player.sockets[slot]=socket;player.sockets.leftHand=leftSocket;}clearStatSnapshots();}
}
function equipmentFilters(petOnly=false){return `<div class="gear-filters"><label>稀有度<select data-gearfilter="rarity"><option value="all">全部稀有度</option>${RARITIES.map(r=>`<option value="${r.id}" ${gearFilterRarity===r.id?'selected':''}>${r.name} · ${r.count}詞</option>`).join('')}</select></label><label>階級<select data-gearfilter="tier"><option value="all">全部階級</option>${TIER_NAMES.map((t,i)=>`<option value="${i+1}" ${gearFilterTier===String(i+1)?'selected':''}>${t}階 Lv.${GEAR_TIERS[i].min}–${GEAR_TIERS[i].max}</option>`).join('')}</select></label><label>部位<select data-gearfilter="slot"><option value="all">全部部位</option>${Object.entries(petOnly?PET_SLOTS:SLOTS).map(([id,label])=>`<option value="${petOnly?'pet-':''}${id}" ${gearFilterSlot===(petOnly?'pet-':'')+id?'selected':''}>${label}</option>`).join('')}</select></label><label>攻擊屬性<select data-gearfilter="stat">${[['all','全部屬性'],['atk','含 ATK 物理攻擊'],['matk','含 MATK 魔法攻擊']].map(([id,label])=>`<option value="${id}" ${gearFilterStat===id?'selected':''}>${label}</option>`).join('')}</select></label>${petOnly?'':`<label>職業適用<select data-gearfilter="job">${[['all','全部職業'],['usable','本職業可用（含通用）'],['unusable','其他職業專用']].map(([id,label])=>`<option value="${id}" ${gearFilterJob===id?'selected':''}>${label}</option>`).join('')}</select></label>`}</div><p class="tiny">ATK／MATK 依裝備基礎值與詞綴篩選。${petOnly?'寵物裝備不限角色職業。':'本職業可用包含通用裝備；穿戴等級仍需另外達標。'}</p>`;}
function matchesGear(g){return matchesGearFilters(g,ITEMS[g.id],{rarity:gearFilterRarity,tier:gearFilterTier,slot:gearFilterSlot,stat:gearFilterStat,job:gearFilterJob},player.job,gearTier(g.level));}

function renderTierGuide(){return `<details class="item" open><summary>裝備傳承 · 八大階段</summary><p>比較同部位、同物理／魔法用途：下一階普通裝備的核心最低值，高於上一階神話的核心最高值。詞條功能仍依配裝取捨。下列為武器ATK詞條範圍，不含角色屬性。</p>${GEAR_TIERS.map(t=>`<p><b>${t.name}</b> · Lv.${t.min}–${t.max} · 核心基準×${t.power}<br>普通ATK ${affixRange('atk',t.tier,'common').join('–')}／神話ATK ${affixRange('atk',t.tier,'mythic').join('–')}<br>${ITEMS[shardId('weapon',t.tier)].name}／${ITEMS[shardId('armor',t.tier)].name}</p>`).join('')}<p>普通2詞／稀有3詞／罕見4詞／傳說5詞／神話6詞；同階數值係數×1／1.12／1.28／1.48／1.72。舊裝備已同步換算，保留身分、等級、品質、穿戴位置及既有可用詞條方向。</p></details>`;}
function renderCrafting(){
 const all=[...Object.entries(GEAR_BASE),...Object.entries(PET_GEAR_BASE)];
 const selected=ITEMS[craftBase]?.slot||ITEMS[craftBase]?.petSlot?craftBase:'blade',group=gearGroup(selected),id=shardId(group,craftTier),owned=player.bag.find(e=>e.id===id)?.qty||0;
 const salvage=`<div class="item"><b>♻ 掛機自動分解／保留規則</b><p>新掉落裝備與勾選的背包掃描共用這套規則。<strong>符合保留條件的留下，其他分解。</strong> 勾選要參與判斷的條件。</p><div class="auto-options"><label><input type="checkbox" data-autosalvage ${player.autoSalvage?'checked':''}> 啟用掛機自動分解</label><label><input type="checkbox" data-salvageotherjobs ${player.salvageOtherJobs?'checked':''}> 自動分解本職業無法使用的裝備</label><p class="tiny">只判斷職業限制，不因等級不足而分解。此選項優先於其他保留條件；通用裝備與寵物裝備仍依原規則處理，融合目標與換裝保護裝備不分解。</p></div><div class="gear-filters"><label>保留方式<select data-salvagemode><option value="any" ${player.salvageMatchMode==='any'?'selected':''}>符合任一條即保留</option><option value="two" ${player.salvageMatchMode==='two'?'selected':''}>至少符合兩條才保留</option><option value="all" ${player.salvageMatchMode==='all'?'selected':''}>全部符合才保留</option></select></label><label><input type="checkbox" data-keeprarity ${player.keepRarity?'checked':''}> 依稀有度保留<select data-salvagelimit>${RARITIES.map(r=>`<option value="${r.id}" ${player.salvageMaxRarity===r.id?'selected':''}>${r.name}及以上</option>`).join('')}</select></label><label><input type="checkbox" data-keeptier ${player.keepTier?'checked':''}> 依階級保留<select data-salvagetier>${TIER_NAMES.map((name,i)=>`<option value="${i+1}" ${player.salvageMaxTier===i+1?'selected':''}>${name}階及以上</option>`).join('')}</select></label><label><input type="checkbox" data-keepstat ${player.keepStat?'checked':''}> 依詞條保留<select data-salvagestat>${SALVAGE_STATS.map(s=>`<option value="${s}" ${player.salvageStat===s?'selected':''}>${s}</option>`).join('')}</select></label><label>詞條數值達到<input data-salvagevalue type="number" min="0" max="999" value="${player.salvageStatBelow}" ${!player.keepStat?'disabled':''}></label></div><p class="tiny">例：勾選「罕見及以上」「星輝階及以上」「STR ≥ 3」，可選符合 1、2、3 條才保留。缺少 STR 視為 0。</p><p class="tiny">未勾選的條件不參與判斷；若保留條件全部取消，僅執行已勾選的職業不符分解；職業選項也關閉時不自動分解任何裝備。普通 1、稀有 2、罕見 3、傳說 5、神話 8 塊碎晶。</p></div>`;
 const craft=`<div class="item"><b>⚒ 同階指定裝備融合</b><p>同階武器或防具碎晶 ×8；寵物裝備使用防具碎晶。</p><div class="gear-filters"><label>階級<select data-crafttier>${TIER_NAMES.map((name,i)=>`<option value="${i+1}" ${craftTier===i+1?'selected':''}>${name}階 Lv.${GEAR_TIERS[i].min}–${GEAR_TIERS[i].max}</option>`).join('')}</select></label><label>指定裝備<select data-craftbase>${all.map(([key,g])=>`<option value="${key}" ${selected===key?'selected':''}>${g.petSlot?'寵物'+PET_SLOTS[g.petSlot]:SLOTS[g.slot]}｜${g.name}</option>`).join('')}</select></label></div><p class="tiny">材料：${ITEMS[id].name} · 持有 ${owned}/8</p><button data-craft ${owned<8?'disabled':''}>融合指定裝備（消耗 8 塊）</button></div>`;
 const active=[player.keepRarity&&`${RARITIES.find(r=>r.id===player.salvageMaxRarity)?.name}以上`,player.keepTier&&`${TIER_NAMES[player.salvageMaxTier-1]}階以上`,player.keepStat&&`${player.salvageStat} ≥ ${player.salvageStatBelow}`].filter(Boolean),rule=player.salvageMatchMode==='all'?'全部':player.salvageMatchMode==='two'?'至少兩條':'至少一條';
 const eligible=player.bag.filter(g=>(ITEMS[g.id]?.slot||ITEMS[g.id]?.petSlot)&&shouldAutoSalvage(g,player)).length;
 const status=`<div class="salvage-status ${player.autoSalvage?'enabled':'disabled'}"><b>${player.autoSalvage?'● 自動分解已啟用':'○ 自動分解未啟用'}</b><p>${!player.autoSalvage?'目前所有裝備掉落都會進背包。':active.length?`保留：${active.join('、')}；符合${rule}才留下，其餘自動拆解。`:(player.salvageOtherJobs?'職業不符的裝備自動分解，其餘保留。':'尚未勾選保留條件，所有裝備保留。')}</p><div class="salvage-existing"><label><input type="checkbox" data-salvageinventory ${player.salvageInventory?'checked':''}> 同時自動整理背包原有的未穿戴裝備</label><p>僅處理背包，絕不拆解角色與寵物正在穿戴的裝備。${player.autoSalvage?`${player.salvageOtherJobs?'職業不符優先分解。':''}目前符合分解條件：${eligible} 件。`:''}</p><button data-salvagebatch ${!player.autoSalvage||!eligible?'disabled':''}>立即整理背包（${eligible} 件）</button></div></div>`;
 return renderTierGuide()+renderAutoFusion()+status+salvage+craft+'<div class="item"><b>稀有度機率</b><p>普通 70% · 稀有 25% · 罕見 4% · 傳說 0.9% · 神話 0.1%。只有神話會出現特殊詞綴；傳說保有更高核心數值與5條一般詞綴；品質同時提高核心數值與詞條數量。首領裝備另採罕見70%／傳說25%／神話5%。</p></div>';
}
function cardComparison(cardId,slot=cardCompareSlots[cardId]||CARDS[cardId]?.slots?.[0]){if(!cardAllowedInSlot(CARDS[cardId],slot))return '<div class="gear-compare">此卡片不能鑲入此部位。</div>';const previous=player.sockets[slot],card=CARDS[cardId];if(!card)return '';const keys=['hp','mp','atk','matk','def','mdef','hit','flee','aspd','crit','critDmg','ignoreDef','magicDamage','damageReduction','aspdPct'],snapshot=()=>{clearStatSnapshots();return {...effectiveAttributes(),...Object.fromEntries(keys.map(k=>[k,stat(k)]))};},before=snapshot();try{player.sockets[slot]=cardId;const after=snapshot(),rows=Object.keys(before).filter(k=>['atk','matk'].includes(k)||Math.abs(after[k]-before[k])>.001).map(k=>{const delta=after[k]-before[k];return `<div class="compare-stat"><span>${k==='mp'?'SP':k.toUpperCase()}</span><span>${Number(before[k].toFixed(2))} → ${Number(after[k].toFixed(2))} <b class="${delta>0?'delta-up':delta<0?'delta-down':'delta-zero'}">${delta>=0?'+':''}${Number(delta.toFixed(2))}</b></span></div>`;}).join('');return `<div class="gear-compare"><b>對比 ${SLOTS[slot]} 的現有卡片</b><p>目前：${CARDS[previous]?.name||'空插槽'}<br>${previous?cardDescription(CARDS[previous],player.level):'沒有卡片加成'}</p><p>換入：${card.name}<br>${cardDescription(card,player.level)}</p><div class="compare-stats">${rows}</div><small>顯示更換後人物總能力；預覽不會消耗、卸下或插入卡片。</small></div>`;}finally{player.sockets[slot]=previous;clearStatSnapshots();}}
function renderCards(){
 let html=`<div class="item"><b>怪物卡片庫 · ${player.cards.reduce((n,c)=>n+c.qty,0)} 張未鑲嵌</b><p>每張卡片限指定部位，每部位1張。已鑲卡片及能力請至「角色 → 角色裝備」查看。卡片綁定角色部位並持續生效，換裝、卸裝、雙手武器與轉職皆保留；只有手動卸卡或換卡才會退回卡片庫。負面效果同樣生效。</p><label>篩選卡片部位<select data-card-filter-slot><option value="all">全部部位</option>${Object.entries(SLOTS).map(([slot,label])=>`<option value="${slot}" ${cardFilterSlot===slot?'selected':''}>${label}</option>`).join('')}</select></label></div>`;
 const returned=player.cardBindingMigration?.returned||[];if(returned.length)html+=`<div class="item quest-ready"><b>舊存檔卡片已安全整理</b><p>上次整理有 ${returned.length} 張不符合新部位限制，已卸回下方卡片庫；合法卡片原位保留。</p>${returned.map(x=>`<p>${CARDS[x.id]?.name||x.id}：原 ${SLOTS[x.slot]} → 卡片庫</p>`).join('')}</div>`;
 const held=player.cards.filter(({id})=>cardFilterSlot==='all'||cardAllowedInSlot(CARDS[id],cardFilterSlot));if(!held.length)html+='<div class="empty">此篩選下尚無可用卡片。</div>';
 html+=held.map(({id,qty})=>{const card=CARDS[id],slots=card.slots,slot=cardFilterSlot!=='all'?cardFilterSlot:slots.includes(cardCompareSlots[id])?cardCompareSlots[id]:slots[0];return `<div class="item"><div class="itemhead"><b>✦ ${card.name} <span class="stack-count">×${qty}</span></b><span class="rarity">${card.boss?'首領專屬':'特色卡片'}</span></div><p>${cardDescription(card,player.level)}</p><b>限定部位：${slots.map(s=>SLOTS[s]).join('／')}</b>${slots.length>1&&cardFilterSlot==='all'?`<label>選擇比較部位<select data-card-compare-slot="${id}">${slots.map(s=>`<option value="${s}" ${slot===s?'selected':''}>${SLOTS[s]} · ${CARDS[player.sockets[s]]?.name||'空插槽'}</option>`).join('')}</select></label>`:''}${cardComparison(id,slot)}<label>出售張數<input type="number" min="1" max="${qty}" value="${sellAmounts['card-'+id]||1}" data-sale-quantity="card-${id}" aria-label="${card.name}出售張數"></label><button data-card-sale="${id}">出售卡片 · 每張${card.boss?1000:200}金</button><button data-socket="${id}:${slot}">鑲入${SLOTS[slot]}${player.sockets[slot]?'（替換現有卡片）':''}</button></div>`;}).join('');
 return html;}

const BAG_GROUPS={consumables:'消耗品',equipment:'角色裝備',petEquipment:'寵物裝備',cards:'卡片',junk:'雜物',tickets:'入場券',quests:'任務道具',shards:'裝備碎片',materials:'進化材料'};
function bagGroup(entry){const it=ITEMS[entry.id];return it.slot?'equipment':it.petSlot?'petEquipment':it.ticket?'tickets':it.quest?'quests':it.craft?'shards':it.junk?'junk':it.evolution?'materials':'consumables';}
function renderBag(){const indexed=player.bag.map((entry,index)=>({entry,index})),count=type=>indexed.filter(x=>bagGroup(x.entry)===type).length;
 let html=`<p class="muted">背包共 ${player.bag.length} 格 · 藥水／碎晶／雜物堆疊，裝備獨立</p><div class="bag-filters">${Object.entries(BAG_GROUPS).map(([id,name])=>`<button data-bagcategory="${id}" class="${bagCategory===id?'active':''}">${name} ${id==='cards'?player.cards.reduce((n,c)=>n+c.qty,0):count(id)}</button>`).join('')}</div>${['equipment','petEquipment'].includes(bagCategory)?equipmentFilters(bagCategory==='petEquipment'):''}`;
 if(bagCategory==='cards')return html+renderCards();const entries=indexed.filter(x=>bagGroup(x.entry)===bagCategory&&(!['equipment','petEquipment'].includes(bagCategory)||matchesGear(x.entry)));html+=entries.map(({entry,index:i})=>{const it=ITEMS[entry.id],gear=!!(it.slot||it.petSlot),petGear=!!it.petSlot;return `<div class="item" data-ui-key="bag-${escapeHtml(entry.uid||entry.id)}"><div class="itemhead"><div>${gear?equipmentLine(entry):`<b>${escapeHtml(it.name)}</b><span class="stack-count">×${entry.qty}</span>`}<p>${gear?`需求 ${petGear?'寵物':'Base'} Lv.${entry.level} · ${petGear?'寵物'+PET_SLOTS[it.petSlot]:SLOTS[it.slot]}${it.hands===2?' · 雙手武器':''}`:it.ticket?it.description:it.thirdSeal?it.description:it.quest?(it.breakthrough?'預備聖證 · 不自動出售（不是天極覺醒聖印）':'轉生任務材料 · 不自動出售'):it.craft?'可用於相同階級裝備融合':it.junk?'雜物，可出售':it.evolution?it.description:it.capture?'捕捉道具':it.heal?`恢復 HP ${potionRestore(it,'hp',player.level,stat('hp'))}${it.healPct?'（Lv.51起含最大HP15%）':''}`:`恢復 SP ${potionRestore(it,'mp',player.level,stat('mp'))}${it.energyPct?'（Lv.51起含最大SP10%）':''}`}</p></div><div class="gear-actions">${it.junk||it.craft||it.evolution||it.quest?'':`<button data-use="${i}" ${it.capture||gear&&(petGear?(activePet()?.level||0):ignoresGearLevel(player,entry)?999:player.level)<entry.level||gear&&!petGear&&it.jobs&&!it.jobs.includes(player.job)?'disabled':''}>${gear?'穿戴':'使用'}</button>`}${gear?`<button data-dismantle="${escapeHtml(entry.uid)}" class="manual-dismantle">手動分解</button>`:''}</div></div>${gear?'':`<div class="manual-sale-row"><label>出售數量<input type="number" min="1" max="${entry.uid?1:entry.qty}" data-sale-quantity="${escapeHtml(entry.uid||entry.id)}" value="${sellAmounts[entry.uid||entry.id]||1}" aria-label="${escapeHtml(it.name)}出售數量"></label><button data-manual-sale="${escapeHtml(entry.uid||entry.id)}">出售 · 每個${manualSalePrice(entry,it)}金</button></div>`}${gear?gearComparison(entry):''}${(it.heal||it.energy)&&activePet()?`<button data-petuse="${i}">給寵物使用</button>`:''}</div>`}).join('')||'<div class="empty">這個分類還沒有物品。</div>';return html;}
function renderAutoBuy(){return `<div class="item autobuy-panel"><b>🛒 掛機自動購買藥水</b><p>藥水由玩家和寵物共用背包。庫存少於設定瓶數時，自動用金幣補到目標數量；不足額時只購買負擔得起的數量。</p>${[['hp','HP 紅水',['red_small','red_mid','red_large']],['sp','SP 藍水',['blue_small','blue_mid','blue_large']]].map(([type,name,ids])=>{const c=player.autoBuyPotions[type];return `<div class="autobuy-row"><label class="autobuy-check"><input type="checkbox" data-autobuy-enabled="${type}" ${c.enabled?'checked':''}> ${name}自動補貨</label><label>選擇藥水<select data-autobuy-id="${type}">${ids.map(id=>`<option value="${id}" ${c.id===id?'selected':''}>${ITEMS[id].name} · ${ITEMS[id].cost} 金</option>`).join('')}</select></label><label>少於幾瓶時<input type="number" min="0" max="200" data-autobuy-min="${type}" value="${c.min}"></label><label>補到幾瓶<input type="number" min="1" max="200" data-autobuy-target="${type}" value="${c.target}"></label><small>目前持有 ${player.bag.find(e=>e.id===c.id)?.qty||0} 瓶</small></div>`}).join('')}</div>`;}
function renderAscensionDetails(p){if(fusedPair(p))return `<p>融合形態：${fusedPair(p).name} · 等級上限200 · ${fusedPair(p).style}</p>`;const cost=ascensionCost(p),reason=ascensionError(p,player.bag,player.location);return `<p>界限進化素材：超越靈核 ${cost.essence_4}＋蒼穹界限靈髓 ${cost.ascension_core}；消耗忠誠度 ${ASCENSION_LOYALTY}（目前 ${p.loyalty||0}／${LOYALTY_MAX}）。${p.rarity==='mythic'?'原有神話維持神話。':'保證提升／維持傳說；不抽神話。'}</p><button data-pet-ascend="${p.id}" ${reason?'disabled':''}>${reason||'進行界限進化'}</button>${p.ascended&&p.rarity==='legendary'?`<p>獨立神話異化：超越靈核50＋界限靈髓20，成功率15%；失敗維持傳說。</p><button data-pet-mutate="${p.id}" ${ascensionError(p,player.bag,player.location,'mutate')?'disabled':''}>嘗試神話異化（15%）</button>`:''}`;}
function renderEvolution(showAtlas=false){if(!['common','rare','uncommon'].includes(evolutionArtRarity))evolutionArtRarity='uncommon';return `<section class="item evolution-altar"><div class="eyebrow">COMPANION EVOLUTION</div><h3>✦ 村莊寵物進化</h3><p>達 Lv.20／40／60／80 後，回城消耗靈核進化。一般品質沿原物種成長；晉升傳說或神話時，會變異成另一種族，整條進化路線、名稱與立繪同步改變。升級不會自動進化。</p><p>普通／稀有／罕見為同型態的不同色彩；傳說與神話則是兩種獨立的種族變異，各有專屬名稱與造型。20～80級的一般進化仍有機會提升品質或變異神話。99級界限進化保證到傳說，不抽神話；原有神話維持神話。</p><details><summary>查看一般品質進化圖鑑</summary><div class="evolution-preview-controls"><label>外觀品質<select id="evolutionArtSelect">${PET_RARITIES.slice(0,3).map(r=>`<option value="${r.id}" ${r.id===evolutionArtRarity?'selected':''}>${r.name}</option>`).join('')}</select></label></div>${Object.entries(PET_FAMILIES).map(([species,role])=>`<h4>${SPECIES[species].roleName}</h4>${PET_PALETTES[evolutionArtRarity]?.[role]?`<p class="pet-palette-note">${PET_PALETTES[evolutionArtRarity][role]} · 專屬配色</p>`:''}<div class="evolution-route">${petRoute({species,rarity:evolutionArtRarity}).map((name,i)=>`<div class="evolution-form">${petSprite({species,evolution:i,rarity:evolutionArtRarity},'evolution')}<small>Lv.${i?i*20:1}</small><b>${name}</b></div>`).join('')}</div>`).join('')}<div class="mutation-mystery"><b>✦ 傳說變異</b><p>可變異進化至傳說品質，成功時揭曉專屬形態。</p><b>✧ 神話覺醒</b><p>任何品質夥伴均有機會直接變異為神話品質，外觀將在成功後揭曉。</p></div></details><details><summary>進化素材與持有數量</summary>${PET_EVOLUTIONS.map((s,i)=>`<p>第 ${i+1} 階 Lv.${s.level}：${ITEMS[s.id].name} ×${s.count} · 持有 ${player.bag.find(e=>e.id===s.id)?.qty||0}<br><small>怪物 ${s.range} 掉落率 22%${i===3?'；Lv.81–99同樣掉落超越靈核':''}</small></p>`).join('')}</details><details><summary>靈核合成 · 低階 3 → 高階 1</summary><p>只能在城鎮合成，讓目前地圖也能取得最終進化素材。</p>${[1,2,3].map(i=>`<p>${ITEMS['essence_'+i].name} ×3 → ${ITEMS['essence_'+(i+1)].name} ×1 <button data-essence="${i}" ${!isTown(player.location)||(player.bag.find(e=>e.id==='essence_'+i)?.qty||0)<3?'disabled':''}>合成</button></p>`).join('')}</details></section>${renderPetFusion()}${player.pets.map(p=>{const step=nextPetEvolution(p),held=step?(player.bag.find(e=>e.id===step.id)?.qty||0):0,rarity=petRarity(p),chance=step?(step.mutation[rarity.id]||0):0,can=step&&p.level>=step.level&&held>=step.count&&isTown(player.location);return `<div class="item evolution-pet"><div class="evolution-pair"><div>${petSprite(p,'evolution')}<b class="grade-${rarity.id}">${escapeHtml(petForm(p)||SPECIES[p.species].name)}</b><small>${rarity.name} · 第 ${evolutionStage(p)} 階</small></div>${step?`<span class="evolution-arrow">→</span><div>${['legendary','mythic'].includes(p.rarity)?'<div class="unknown-form" aria-label="進化後形態尚未揭曉">?</div><b>未知的進化形態</b>':`${petSprite(p,'evolution',evolutionStage(p)+1)}<b>${escapeHtml(petForm(p,evolutionStage(p)+1)||SPECIES[p.species].name)}</b>`}<small>下一形態 · Lv.${step.level}</small></div>`:''}</div><p>夥伴：${escapeHtml(p.nickname)} · Lv.${p.level}</p>${step?`<p>${ITEMS[step.id].name} ${held}/${step.count} · 直達神話機率 ${(chance*100).toFixed(1)}%</p><small>預覽為目前品質的下一階；若升為傳說或神話，將轉入對應變異種族，名稱與立繪一起改變。</small><button data-evolve="${p.id}" ${can?'':'disabled'}>${!isTown(player.location)?'回城後可進化':p.level<step.level?`需要 Lv.${step.level}`:held<step.count?'素材不足':'執行進化'}</button>`:`<p>✦ ${p.ascended?'已完成界限進化':'已達一般最終形態'}</p>${renderAscensionDetails(p)}`}</div>`}).join('')}`;}

function openPanel(id){if(id==='shop'&&!isTown(player.location))return toast('商店只在村莊開放');if(['quests','guild'].includes(id)&&player.location!=='town')return toast('請回村莊辦理公會事務');if(['skills','gear','attributes'].includes(id)){characterSection=id;id='character';}if(id==='cards'){bagCategory='cards';id='bag';}if(id==='evolution'){petSection='manage';id='pets';}if(id==='reports')id='codex';tab=id;render();if(window.innerWidth<1100)$('collectionPanel')?.scrollIntoView({behavior:'smooth',block:'start'});}
function renderAutomation(){return `<div class="item"><b>離線掛機 · 最多 24 小時</b><p>離開時開啟自動戰鬥，回來後依此角色的地圖、寵物、技能與補給設定補算。死亡或背包接近容量上限時停止；城鎮及暫停戰鬥沒有收益。不會捕捉、進化或融合。舊存檔首次進入後才開始記錄離線時間。</p></div><div class="item"><b>掛機設定</b><p>設定會自動儲存。補給使用背包中的藥水，只有開啟自動購買時才會花費金幣。</p><div class="panel-shortcuts"><button data-preset="safe">套用穩健掛機</button><button data-preset="manual">改用手動補給</button></div><small>穩健掛機：四種自動補給與終極共鳴開啟、遇首領逃走；不會自動開啟購買。</small></div><div class="item"><b>自動復活、首領避戰與共鳴</b><label class="setting-toggle"><input type="checkbox" data-auto-revive ${player.autoRevive?'checked':''}> 金幣自動復活（線上／離線）</label><p>只支付金幣原地復活；金幣不足會免費回城並停止掛機，不使用其他資源。</p><p>僅一般練功區有地圖首領，寵物之地沒有首領。首領卡片掉率0.1%，一般怪物卡片0.2%。</p><label class="setting-toggle"><input type="checkbox" data-escape-boss ${player.autoEscapeBoss?'checked':''}> 遇到首領立即逃走</label><label class="setting-toggle"><input type="checkbox" data-autoultimate ${player.autoUltimate?'checked':''}> 能量足夠時自動施放終極共鳴</label></div>`+renderCaptureSettings()+renderJunkSettings()+renderPotionSettings()+renderAutoBuy()+`<button class="wide" data-open="salvage">前往工坊設定自動分解與融合</button>`;}
function renderOverview(){return `<div class="item overview-intro"><span class="eyebrow">ADVENTURE GUIDE</span><h3>${player.location==='petland'?'尋找你的靈契夥伴':isTown(player.location)?'整備好，再出發':'正在冒險'}</h3><p>${mapRules(player.location).summary}</p>${!activePet()?'<p>可手動直接丟球，或在掛機設定選擇自動捕捉類型，不需壓低血量。</p>':''}<div class="panel-shortcuts"><button data-open="pets">管理夥伴</button><button data-open="bag">整理背包</button><button data-open="settings">掛機設定</button></div></div>`+renderFormation()+`<details class="item" data-ui-key="full-stats"><summary>查看人物與寵物完整數值</summary>${renderCombatPanel()}</details>`;}
