function start(name,job){if(creatingSlot===null)return;try{const index=creatingSlot,candidate=normalize(fresh(name.trim().slice(0,16)||'無名冒險者',job));writeCharacterSlot(localStorage,index,candidate);selectedSlot=index;closeCharacterCreation();renderEntry();toast('角色已建立，請選擇後按「進入遊戲」');}catch(error){toast('建立失敗：'+error.message);}}
