async function enterCharacterSlot(index){if(settlingOffline)return;const slot=readCharacterSlot(localStorage,index,normalize,valid);if(!slot.player)return toast(slot.error||'請先建立或導入角色');resetSession();activeSlot=index;selectedSlot=index;player=slot.player;gameRunning=false;auto=!player.manualPaused&&!player.autoStoppedReason;let offlineSummary;try{offlineSummary=await settleOffline();}catch(error){player=null;activeSlot=null;renderEntry();toast(error.message);return;}resetSession();gameRunning=true;selectedContinent=continentFor(player.location);renderMapChoices();player.hp=Math.min(player.hp,stat('hp'));player.mp=Math.min(player.mp,stat('mp'));$('entryScreen').hidden=true;$('gameShell').hidden=false;$('gameShell').inert=false;$('createModal').style.display='none';$('activeSlotLabel').textContent=`第 ${index+1} 格`;message(`歡迎，${player.name}！已進入第 ${index+1} 格的獨立冒險。`,'good');spawn();save();if(!player.hp&&!player.autoRevive)showReviveDialog();if(player.fusionNotice)showFusionResult();if(offlineSummary)showOfflineReport(offlineSummary);if(document.hidden)backgroundPaused=true;}
