function renderEncounterSlots(){const capacity=encounterLimit(player.location);if(!capacity)return '<div class="enemy-idle">安全區域，沒有敵人。</div>';const card=foe=>`<button class="enemy-target ${enemy===foe?'active':''} ${foe.boss?'map-boss':''}" data-target="${foe.instanceId}">${spriteHtml(foe.id,'monster')}<span class="enemy-label">${foe.boss?'♛ 首領 ':''}Lv.${foe.level||1} ${SPECIES[foe.id].name}</span><span class="enemy-hp">${foe.hp}/${foe.maxHp} HP</span>${meter(foe.hp,foe.maxHp,'red')}<small>${enemy===foe?'◎ 目前鎖定':'點擊指定'}</small></button>`;return Array.from({length:capacity},(_,slot)=>{const foe=enemies.find(e=>!e.boss&&e.hp>0&&e.slotIndex===slot);return foe?card(foe):`<div class="enemy-target empty-slot" data-ui-key="empty-${slot}"><span>探索中</span><small>此格獨立隨機遇怪</small></div>`;}).join('')+enemies.filter(e=>e.boss&&e.hp>0).map(card).join('');}

function combatTick(now=gameNow()){inCombatTick=true;if(!offlineSimulation)clearStatSnapshots();try{if(!player.hp){casting=null;if(auto&&player.autoRevive)autoRevivePlayer();if(!offlineSimulation&&$('reviveModal').style.display==='flex')showReviveDialog();return;}if(now>(timers.petShieldExpires||Infinity)){player.shield=Math.max(0,player.shield-petShield);petShield=0;}if(now>(timers.playerShieldExpires||Infinity))player.shield=Math.min(player.shield,petShield);if(now>(petEffects.shieldExpires||Infinity))petEffects.shield=0;
 tickEncounters(now);chooseAttackTarget();autoCapturePet(now);if(casting&&now>=casting.until){const id=casting.id;casting=null;playerAttack(true,id,true);}if(casting&&!player.hp)casting=null;
 if(now-timers.regen>=4000){timers.regen=now;const pet=activePet();if(pet&&pet.hp>0)pet.sp=Math.min(petStats(pet).sp,pet.sp+Math.max(1,Math.ceil(pet.level/8)));player.mp=Math.min(stat('mp'),player.mp+2+passiveBonus('spRegen')+cardBonus('spRegen'));dirty=true;}
 if(enemy.hp&&player.hp){if(auto&&now-(timers.potions||0)>800){timers.potions=now;autoUsePotions();}tickPetEffects(now);const selected=enemy;for(const foe of [...enemies]){if(!player.hp)break;if(foe.hp&&now-foe.lastAttack>=aspdAttackIntervalMs(foe.aspd)){foe.lastAttack=now;enemy=foe;enemyAttack();}}enemy=selectEncounterTarget(enemies,player.targetPriority,selected)||selected;if(enemy.hp&&auto){const companion=activePet();if(companion?.hp>0)petAutoAbility(companion,petStats(companion),now);if(enemy.hp)petAttack();if(enemy.hp)autoCastJobs();if(enemy.hp)playerAttack();if(enemy.hp&&player.autoUltimate&&player.resonance>=ULTIMATE_COST&&now-timers.ultimate>=ULTIMATE_COOLDOWN)ultimate();}}
}finally{inCombatTick=false;if(!offlineSimulation)clearStatSnapshots();}}
async function simulateOffline(state,now=Date.now(),progress=()=>{}){
 const window=offlineWindow(state,now),before=structuredClone(state);
 if(!window.eligible)return {player:state,summary:null};
 clearStatSnapshots();offlineSimulation=true;offlineClock=state.offline.at;offlineMetrics={baseXp:0,jobXp:0,petXp:0,goldEarned:0,potions:{},purchased:{},spent:0,bossesEscaped:0};
 try{
  player=normalize(structuredClone(state));player.hp=Math.min(player.hp,stat('hp'));player.mp=Math.min(player.mp,stat('mp'));resetSession();auto=true;spawn();let simulated=0,reason='已完成離線時間';
  for(;simulated<window.duration;){
   if(!player.hp){if(player.autoRevive&&auto)autoRevivePlayer();if(!player.hp&&auto&&player.autoRevive&&gameNow()<player.reviveAt){const wait=Math.min(window.duration-simulated,player.reviveAt-gameNow());offlineClock+=wait;simulated+=wait;continue;}if(!player.hp||!auto||isTown(player.location)){reason=isTown(player.location)?'金幣不足，已回城停止掛機':'角色倒下，掛機停止';break;}}
   if(player.bag.length>=1900){reason='背包接近容量上限，掛機停止';break;}
   const delta=Math.min(OFFLINE_STEP_MS,window.duration-simulated);offlineClock+=delta;simulated+=delta;combatTick(offlineClock);
   if(offlineClock-(timers.offlineSupplies||0)>=4000){timers.offlineSupplies=offlineClock;if(player.hp>0)autoBuyPotions();if(player.autoSalvage&&player.salvageInventory)salvageBagEquipment();}
   if(Math.floor(simulated/OFFLINE_STEP_MS)%1000===0){progress(simulated/window.duration);await new Promise(resolve=>setTimeout(resolve,0));}
  }
  if(!player.hp)reason='角色倒下，掛機停止';
  const summary={...window,simulated,reason,map:state.location,kills:player.kills-before.kills,gold:player.gold-before.gold,baseBefore:before.level,baseAfter:player.level,jobBefore:before.jobLevel,jobAfter:player.jobLevel,...offlineMetrics,...inventoryDelta(before,player)};
  return {player,summary};
 }finally{clearStatSnapshots();offlineClock=null;offlineSimulation=false;offlineMetrics=null;}
}
function showOfflineReport(summary){
 if(!summary)return;const modal=$('offlineModal');$('offlineTitle').textContent='歡迎回來，離線掛機已結算';
 $('offlineContent').innerHTML=`<p>${escapeHtml(MAPS[summary.map]?.name||summary.map)} · 離開 ${offlineDuration(summary.elapsed)}<br>實際掛機 ${offlineDuration(summary.simulated)}${summary.capped?' · 已套用 24 小時上限':''}</p><p>${escapeHtml(summary.reason)}</p><div class="offline-totals"><div>擊殺<b>${summary.kills.toLocaleString()} 隻</b></div><div>金幣淨收益<b>${summary.gold>=0?'+':''}${summary.gold.toLocaleString()}</b></div><div>Base EXP<b>+${summary.baseXp.toLocaleString()}</b></div><div>Job EXP<b>+${summary.jobXp.toLocaleString()}</b></div><div>寵物 EXP<b>+${summary.petXp.toLocaleString()}</b></div><div>掉落裝備保留<b>${summary.equipment.length} 件</b></div></div><p>Base Level ${summary.baseBefore} → ${summary.baseAfter} · Job Level ${summary.jobBefore} → ${summary.jobAfter}<br>金幣獲得 ${summary.goldEarned.toLocaleString()} · 補給／復活支出 ${summary.spent.toLocaleString()} · 自動復活 ${summary.revives||0} 次 · 避開首領 ${summary.bossesEscaped} 隻</p><details><summary>補給與掉落明細</summary><p>消耗藥水：${Object.entries(summary.potions).map(([id,qty])=>`${escapeHtml(ITEMS[id]?.name||id)} ×${qty}`).join('、')||'無'}</p><p>購入藥水：${Object.entries(summary.purchased).map(([id,qty])=>`${escapeHtml(ITEMS[id]?.name||id)} ×${qty}`).join('、')||'無'}</p><p>背包堆疊物品淨變動：${summary.stacks.map(e=>`${escapeHtml(ITEMS[e.id]?.name||e.id)} ${e.qty>0?'+':''}${e.qty}`).join('、')||'無'}</p><p>卡片：${summary.cards.map(e=>`${escapeHtml(CARDS[e.id]?.name||e.id)} ×${e.qty}`).join('、')||'無'}</p><p>保留裝備：${summary.equipment.map(e=>`${escapeHtml(RARITIES.find(r=>r.id===e.rarity)?.name||'')} ${escapeHtml(e.name)}`).join('、')||'無'}</p></details><p class="tiny">收益已自動存入此角色；不需額外領取。依目前配置與原掉落規則補算，收益可能與即時戰鬥略有差異；滿級後的 EXP 不會繼續累積。</p>`;modal.hidden=false;$('offlineClose').focus();
}
async function settleOffline(){
 const now=Date.now(),window=offlineWindow(player,now);if(!window.eligible)return null;
 const slotIndex=activeSlot,raw=localStorage.getItem(characterSlotKey(slotIndex));settlingOffline=true;$('entryScreen').inert=true;$('gameShell').inert=true;
 $('offlineProgress').hidden=false;$('offlineProgressText').textContent='正在補算離線掛機… 0%';
 let worker;
 try{
  const result=await new Promise((resolve,reject)=>{
   worker=new Worker(new URL('offline-worker.js?v=6.1.0',document.baseURI),{type:'module'});
   worker.onmessage=event=>{if(event.data.type==='progress')$('offlineProgressText').textContent=`正在補算離線掛機… ${Math.floor(event.data.value*100)}%`;else if(event.data.type==='result')resolve(event.data.result);else reject(Error(event.data.message||'離線結算失敗'));};
   worker.onerror=()=>reject(Error('離線結算載入失敗，請重新整理再試'));
   worker.postMessage({player:structuredClone(player),now});
  });
  if(raw!==localStorage.getItem(characterSlotKey(slotIndex)))throw Error('此角色存檔已在其他分頁變更，請重新選擇角色');
  const previous=player;player=result.player;if(player.autoStoppedReason)auto=false;player.offline={at:Date.now(),enabled:auto};
  if(!valid(player)){player=previous;throw Error('離線結算資料驗證失敗，原存檔已保留');}
  try{writeCharacterSlot(localStorage,slotIndex,player);}catch(error){player=previous;throw Error('儲存空間不足，原存檔與離線時間已保留');}
  return result.summary;
 }finally{worker?.terminate();settlingOffline=false;$('offlineProgress').hidden=true;$('entryScreen').inert=false;$('gameShell').inert=false;}
}

function init(){if(typeof document==='undefined'){self.onmessage=async event=>{try{const result=await simulateOffline(event.data.player,event.data.now,value=>self.postMessage({type:'progress',value}));self.postMessage({type:'result',result});}catch(error){self.postMessage({type:'error',message:error.message});}};return;}$('returnLastMap').onclick=()=>{if(player.lastMap)travel(player.lastMap);};$('captureRewardClose').onclick=()=>{$('captureRewardModal').hidden=true;};$('evolutionStart').onclick=beginEvolution;$('evolutionClose').onclick=closeEvolution;
 $('enterGameBtn').onclick=()=>enterCharacterSlot(selectedSlot);$('returnEntryBtn').onclick=()=>returnToEntry();$('cancelCreateBtn').onclick=closeCharacterCreation;$('fusionQuickStop').onclick=()=>{stopAutoFusion();renderSide()};$('fusionResultClose').onclick=()=>closeFusionResult();$('fusionResultBag').onclick=()=>closeFusionResult(true);

 const closeRename=()=>$('renameModal').style.display='none';$('renameCancel').onclick=closeRename;$('renameForm').onsubmit=e=>{e.preventDefault();const name=$('renameInput').value.trim().slice(0,16);if(!name)return toast('請輸入角色名稱');player.name=name;save();closeRename();render();toast('角色名稱已更新');};

 $('logFilters')?.querySelectorAll('[data-logview]').forEach(b=>b.onclick=()=>{logView=b.dataset.logview;$('logFilters').querySelectorAll('[data-logview]').forEach(x=>x.classList.toggle('active',x===b));renderLog()});
 $('classChoices').innerHTML=Object.entries(CLASSES).filter(([id])=>!SECOND_JOBS[id]).map(([id,c])=>`<button data-class="${id}" class="${id==='swordsman'?'active':''}"><b>${c.symbol} ${c.name}</b><small>${({swordsman:'近戰 / 耐久',acolyte:'治療 / 聖屬性',mage:'元素 / 魔法',thief:'高速 / 爆擊',archer:'遠程 / 命中 / 精準'})[id]}</small><span class="class-range">${rangeLabel(playerRange(id))}</span></button>`).join('');
 for(const b of $('classChoices').querySelectorAll('[data-class]'))b.insertAdjacentHTML('afterbegin',spriteHtml(b.dataset.class,'choice'));
 document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{selectedClass=b.dataset.class;document.querySelectorAll('[data-class]').forEach(x=>x.classList.toggle('active',x===b))});
 $('createBtn').onclick=()=>start($('nameInput').value,selectedClass);$('nameInput').onkeydown=e=>{if(e.key==='Enter')$('createBtn').click()};
 $('attackBtn').onclick=()=>playerAttack();$('skillBtn').onclick=()=>playerAttack(true);$('tacticBtn').onclick=classTactic;$('ultimateBtn').onclick=ultimate;$('captureBtn').onclick=capture;$('fleeBossBtn').onclick=fleeMapBosses;$('autoBtn').onclick=()=>{auto=!auto;player.manualPaused=!auto;if(auto)delete player.autoStoppedReason;save();render()};$('saveBtn').onclick=()=>save(true);
 $('reviveYes').onclick=()=>revive('place');$('reviveTown').onclick=()=>revive('town');$('reviveLater').onclick=()=>$('reviveModal').style.display='none';
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openPanel(b.dataset.tab));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{const id=b.dataset.nav;if(id==='adventure')$('battlePanel').scrollIntoView({behavior:'smooth',block:'start'});else if(id==='character')$('characterPanel').scrollIntoView({behavior:'smooth',block:'start'});else openPanel(id);});for(const b of document.querySelectorAll('[data-travel]'))b.onclick=()=>travel(b.dataset.travel==='town'?homeTown(player.location):b.dataset.travel);
 renderMapChoices();$('continentSelect').onchange=()=>{selectedContinent=$('continentSelect').value;renderMapChoices();};
 $('mapSelect').onchange=e=>{if(player)travel(e.target.value)};
 $('exportBtn').onclick=exportSave;$('importBtn').onclick=()=>{importTargetSlot=activeSlot;$('saveFile').click()};$('saveFile').onchange=async e=>{if(e.target.files[0])await importSave(e.target.files[0]);e.target.value=''};
 $('resetBtn').onclick=()=>{const index=activeSlot;if(index!==null&&returnToEntry())openCharacterCreation(index);};
 try{migrateLegacyCharacter(localStorage,load());const first=lobbySlots().find(slot=>slot.player);selectedSlot=first?.index??0;renderEntry();}catch(error){toast('無法讀取本機存檔：'+error.message);}
 $('gameShell').hidden=true;$('entryScreen').hidden=false;$('createModal').style.display='none';

 setInterval(()=>{if(gameRunning&&player&&!offlineSimulation&&!document.hidden){if(player.hp<=0&&$('reviveModal').style.display==='flex')showReviveDialog();const pet=activePet();if(pet?.hp<=0)render();}},1000);
 setInterval(()=>{if(evolutionRunning||settlingOffline||backgroundPaused||document.hidden||!gameRunning||!player||!enemy)return;combatTick();if(dirty&&gameNow()-lastSave>4500)save();},20);
 setInterval(()=>{if(!settlingOffline&&!backgroundPaused&&!document.hidden&&gameRunning&&player&&auto){if(player.hp>0)autoBuyPotions();if(player.autoSalvage&&player.salvageInventory)salvageBagEquipment();autoSellSelected();if(dirty)save();}},4000);
 setInterval(()=>{if(!document.hidden&&!settlingOffline&&!backgroundPaused)autoFusionTick();},250);
 window.addEventListener('pagehide',()=>{if(gameRunning&&!settlingOffline&&!backgroundPaused)save()});
 document.addEventListener('visibilitychange',async()=>{
  if(document.hidden){if(gameRunning&&!settlingOffline){save();backgroundPaused=true;}return;}
  if(!backgroundPaused||!gameRunning||settlingOffline)return;backgroundPaused=false;
  try{const summary=await settleOffline();resetSession();spawn();save();if(summary)showOfflineReport(summary);if(!player.hp&&!player.autoRevive)showReviveDialog();}catch(error){returnToEntry(false);toast(error.message);}
 });
 $('offlineClose').onclick=()=>{$('offlineModal').hidden=true;if(!player.hp&&!player.autoRevive)showReviveDialog();};
}


function sellManual(key){const entry=player.bag.find(e=>(e.uid||e.id)===key),it=ITEMS[entry?.id];if(!entry)return;const qty=sellAmounts[key]||1;if((it.quest||it.evolution||it.craft||entry.fusionMatch||entry.swapProtected)&&!confirm(`確定手動出售 ${it.name} ×${qty}？這項材料或裝備將不再保留。`))return;const result=sellBagEntry(player,key,qty,ITEMS);if(result.error)return toast(result.error);delete sellAmounts[key];message(`出售 ${result.name} ×${result.qty}，獲得 ${result.gold} 金。`,'good','system');dirty=true;save();render();renderSide(true);}
function sellOwnedCard(id){const held=player.cards.find(c=>c.id===id),qty=sellAmounts['card-'+id]||1;if(!held||!Number.isInteger(qty)||qty<1||qty>held.qty)return toast('卡片出售數量不正確');if(!confirm(`確定出售 ${CARDS[id].name} ×${qty}？已鑲嵌卡片不受影響。`))return;held.qty-=qty;player.cards=player.cards.filter(c=>c.qty>0);player.gold+=qty*(CARDS[id].boss?1000:200);dirty=true;save();render();renderSide(true);}
function openAscension(id,mode='ascend'){const pet=player.pets.find(p=>p.id===id),error=ascensionError(pet,player.bag,player.location,mode);if(error)return toast(error);evolutionPreview={id,before:structuredClone(pet),ascension:true,mode};$('evolutionModal').style.display='grid';$('gameShell').inert=true;$('evolutionScene').className='evolution-scene preview';$('evolutionBefore').src=petArt(pet);$('evolutionAfter').src=petArt(pet);$('evolutionTitle').textContent=mode==='mutate'?'神話異化儀式':'夥伴界限進化';const cost=ascensionCost(pet,mode);$('evolutionStatus').textContent=mode==='mutate'?'消耗超越靈核50＋蒼穹界限靈髓20；15%變異神話，失敗保留傳說。':`消耗超越靈核${cost.essence_4}＋蒼穹界限靈髓${cost.ascension_core}＋忠誠度${ASCENSION_LOYALTY}；${pet.rarity==='mythic'?'維持神話並界限進化':'保證傳說界限形態，不抽神話'}。`;$('evolutionStart').hidden=false;$('evolutionStart').disabled=false;$('evolutionClose').disabled=false;$('evolutionClose').textContent='取消';}
function telemetryHtml(){const now=gameNow();combatSamples=combatSamples.filter(x=>now-x.at<=60000);const seconds=Math.max(1,Math.min(60,(now-(combatStarted||now))/1000)),total=combatSamples.reduce((a,x)=>({owner:a.owner+x.owner,pet:a.pet+x.pet,kills:a.kills+x.kills}),{owner:0,pet:0,kills:0});return `<b>擊殺／分鐘 ${(total.kills*60/seconds).toFixed(1)}</b><span>主人 DPS ${Math.round(total.owner/seconds).toLocaleString()}</span><span>寵物 DPS ${Math.round(total.pet/seconds).toLocaleString()}</span><small>依傷害、共鳴與增益來源歸因；最近60秒有效傷害，未滿1分鐘依經過時間折算</small>`;}

function renderThirdResonanceGuide(){return [false,true].map(third=>`<div class="item"><h3>${third?'三轉':'進階二轉'} × 六種融合寵物 · 60種共鳴搭配</h3><p>${third?'三轉主攻、範圍與終結技各有獨立效果，不沿用二轉共鳴；未融合的三轉寵物也使用三轉專屬戰契。':'先完成寵物融合、人物尚未三轉也能使用；未習得轉生主攻時，由原本二轉主攻觸發。'}融合順序只改外觀，能力與技能相同。</p>${Object.entries(THIRD_JOBS).map(([job,meta])=>`<details><summary>${third?meta.name:SECOND_JOBS[job].name}</summary>${Object.entries(FUSION_PAIRS).map(([key,pair])=>{const [main,sub]=key.split('-'),pet={species:({attack:'fang',magic:'wisp',defense:'shell',support:'sprout'})[main],fusion:{main,sub}},rule=companionResonance({job,thirdJob:third,reborn:true,level:player.level},pet);return `<p><b>${pair.name} · ${rule.name}</b><br>${rule.description}</p>`;}).join('')}</details>`).join('')}</div>`).join('');}

let selectedContinent='icarus';
function renderMapChoices(){if(offlineSimulation)return;const selected=CONTINENTS[selectedContinent]?selectedContinent:'icarus';$('continentSelect').value=selected;$('mapSelect').innerHTML=(selected==='sky'?'<option value="skycity">🏙️ 蒼穹樞城</option>':'<option value="town">🏰 靈契主城</option><option value="petland">🌿 寵物之地 · 可捕捉</option>')+ZONES.filter(z=>(z.min>=101?'sky':'icarus')===selected).map(z=>`<option value="${z.id}">${z.icon} Lv.${z.min}–${z.max} ${z.name}</option>`).join('');if(player&&continentFor(player.location)===selected)$('mapSelect').value=player.location;else if(player)$('mapSelect').insertAdjacentHTML('afterbegin','<option value="" disabled selected>請選擇目的地</option>');}
function renderThirdTransfer(){const reason=thirdJobError(player),meta=THIRD_JOBS[player.job];return `<div class="item"><h3>覺醒導師・賽菈</h3><p>${player.thirdJob?`已完成三轉：${meta.name}`:`${SECOND_JOBS[player.job]?.name||'二轉職業'} → ${meta?.name||'三轉職業'}`}</p><p>需要Base150／轉生二轉Job70、${THIRD_SEAL_NAME}10枚。150級天極斷界龍掉落率5%。目前持有 ${player.bag.find(x=>x.id===THIRD_SEAL)?.qty||0}／10枚。</p><p>三轉保留人物等級、配點、全部原有技能、裝備、卡片與寵物；Job重設1、上限70。五個主動技能各10級、四個被動各5級，共70點，Job1先學主攻1級，之後每級給1點。Base上限開放200；寵物需各自融合進化後才能突破150。</p><button data-third-transfer ${reason?'disabled':''}>${reason||'消耗10枚聖印，進行三轉'}</button></div>`;}
function thirdTransfer(){const error=thirdJobError(player);if(error)return toast(error);if(!confirm(`確認轉為${THIRD_JOBS[player.job].name}？消耗天極覺醒聖印10枚，保留裝備與舊技能，Job回到1；人物上限200。`))return;const previous=structuredClone(player);const seals=player.bag.find(x=>x.id===THIRD_SEAL);seals.qty-=10;player.bag=player.bag.filter(x=>x.id!==THIRD_SEAL||x.qty>0);player.secondJobLevel=player.jobLevel;player.thirdJob=true;player.jobLevel=1;player.jobXp=0;player.jobSkills['thirdMain_'+player.job]=1;reconcileSkillPoints(player,JOB_SKILLS[player.job],true);const old='rebirthMain_'+player.job;player.autoSkills.order=player.autoSkills.order.map(id=>id===old?'thirdMain_'+player.job:id);player.equippedJobSkill='thirdMain_'+player.job;clearStatSnapshots();player.hp=stat('hp');player.mp=stat('mp');dirty=true;if(save()===false){player=previous;return;}message(`三轉完成！【${THIRD_JOBS[player.job].name}】開放151–200級。`,'rare');render();}
function renderPetFusion(){return `<section class="item fusion-pet-panel"><h3>✧ 150級融合進化</h3><p>僅在蒼穹樞城進行。兩隻不同系列、150級、已界限進化的神話寵物融合。主素材保留自身裝備、等級150；副素材永久消耗，副素材裝備退回背包。兩者IV取平均。融合後才可升至151，上限200。</p><p>主／副順序只改名稱與外觀；六種配對的能力、技能、距離與共鳴一致。鎖定寵物請先解除鎖定。</p>${Object.entries(FUSION_PAIRS).map(([key,meta])=>`<details><summary>${meta.name} · ${key.split('-').map(role=>({attack:'攻擊',magic:'魔法',defense:'防禦',support:'輔助'})[role]).join('＋')}</summary><p>${meta.style}；融合技能3選2。</p></details>`).join('')}${player.pets.filter(p=>p.rarity==='mythic'&&p.ascended&&p.level>=150&&!p.fusion).map(p=>`<div class="skill-option"><b>主素材：${escapeHtml(p.nickname)}</b><label>選擇副素材<select data-pet-fuse-donor="${p.id}" aria-label="${escapeHtml(p.nickname)}的融合副素材">${player.pets.filter(q=>q.id!==p.id&&q.rarity==='mythic'&&q.ascended&&q.level>=150&&!q.fusion&&PET_FAMILIES[q.species]!==PET_FAMILIES[p.species]).map(q=>`<option value="${q.id}">${escapeHtml(q.nickname)} · Lv.${q.level}${q.locked?' · 已鎖定':''}</option>`).join('')}</select></label><button data-pet-fuse="${p.id}" ${player.location!=='skycity'||p.locked?'disabled':''}>預覽融合與消耗</button></div>`).join('')}</section>`;}
function openPetFusion(id){const select=$('side').querySelector(`[data-pet-fuse-donor="${id}"]`),donorId=select?.value,error=fusionPetError(player,id,donorId);if(error)return toast(error);const pet=player.pets.find(p=>p.id===id),donor=player.pets.find(p=>p.id===donorId);evolutionPreview={id,donorId,fusion:true,before:structuredClone(pet)};$('evolutionModal').style.display='grid';$('gameShell').inert=true;$('evolutionScene').className='evolution-scene preview';$('evolutionBefore').src=petArt(pet);$('evolutionAfter').src=petArt(pet);$('evolutionTitle').textContent='雙靈融合儀式';$('evolutionStatus').textContent=`主素材 ${pet.nickname} ＋ 副素材 ${donor.nickname}。副素材將永久消耗，其裝備退回背包；結果必為神話融合形態，上限200。`;$('evolutionStart').hidden=false;$('evolutionStart').disabled=false;$('evolutionClose').disabled=false;$('evolutionClose').textContent='取消';}

